    grammar: {
      title: 'Tỉnh lược và Thay thế trong Liên kết Văn bản (Ellipsis & Substitution)',
      summaryVi:
        'Ở trình độ C1, người viết và nói tránh lặp từ nặng nề bằng cách thay thế cả cụm động từ/mệnh đề với "do so", "so / not", "one / ones", "that / those", hoặc tỉnh lược phần lặp sau trợ động từ.',
      formula:
        'Thay cụm động từ: do so / did so / done so | Thay mệnh đề sau think/hope/expect/believe: so / not | Thay danh từ so sánh: that of (số ít) / those of (số nhiều)',
      usageVi: [
        '"do so" (hoặc "doing so / done so") thay thế trang trọng cho cả cụm động từ + tân ngữ vừa nhắc tới.',
        '"that of" / "those of" cực kỳ quan trọng trong so sánh C1 ("The resilience of our grid exceeds that of older networks").',
        'Tỉnh lược sau "to" hoặc trợ động từ ("We expected the system to adapt, and it did" / "They urged us to calibrate early, so we plan to").',
      ],
      examples: [
        { en: 'Regulators asked firms to audit their algorithms, and most agreed to do so.', vi: 'Cơ quan quản lý yêu cầu doanh nghiệp kiểm toán thuật toán, và đa số đồng ý làm vậy.', highlight: 'do so' },
        { en: 'The auditability of modern models far exceeds that of early black-box systems.', vi: 'Khả năng kiểm toán của mô hình hiện đại vượt xa các hệ thống hộp đen đời đầu.', highlight: 'that of' },
        { en: 'Will regulatory fragmentation slow cross-border trade? Analysts fear so.', vi: 'Phân mảnh quy định có làm chậm thương mại xuyên biên giới không? Giới phân tích e là có.', highlight: 'fear so' },
      ],
      commonMistakes: [
        { wrong: 'The latency of System A is lower than System B.', right: 'The latency of System A is lower than that of System B.', explanationVi: 'Phải so sánh cùng đối tượng: độ trễ ("latency") của A với độ trễ ("that") của B.' },
        { wrong: 'He asked whether compliance would tighten, and I believe yes.', right: 'He asked whether compliance would tighten, and I believe so.', explanationVi: 'Sau "believe / think / expect / hope / fear", dùng "so" (không dùng "yes") để thay cho mệnh đề khẳng định.' },
      ],
      miniPractice: [
        { id: 'c1-05-g1', prompt: 'The resilience of decentralized networks is substantially higher than ___ centralized ones.', options: ['this of', 'that of', 'those of', 'it of'], correctIndex: 1, explanationVi: '"resilience" là danh từ không đếm được (số ít) -> dùng "that of" để thay thế.' },
        { id: 'c1-05-g2', prompt: 'Although the agency urged vendors to publish safety benchmarks, few chose to ___.', options: ['make so', 'do so', 'be so', 'have so'], correctIndex: 1, explanationVi: 'Cụm cố định "do so" thay thế cho hành động "publish safety benchmarks".' },
        { id: 'c1-05-g3', prompt: 'Could fragmentation delay international standards? Many observers suspect ___.', options: ['yes', 'that', 'so', 'it'], correctIndex: 2, explanationVi: 'Sau "suspect / think / believe / hope", dùng "so" để thay thế mệnh đề khẳng định phía trước.' },
      ],
    },
    customQuiz: [
      { type: 'sentence_pattern', question: 'Câu nào sử dụng "do so" đúng chuẩn C1 để tránh lặp lại cụm động từ dài?', options: ['Several agencies modernized their governance frameworks, and regional partners soon did so as well.', 'Several agencies modernized frameworks, and partners made so.', 'Partners did so modernized frameworks quickly.', 'Modernizing frameworks, partners so did.'], correctIndex: 0, explanationVi: '"did so" thay thế gọn gàng cho "modernized their governance frameworks".' },
      { type: 'sentence_pattern', question: 'Câu nào thể hiện cách tiếp cận tư duy hệ thống (Systems Thinking) rõ ràng nhất?', options: ['Rather than treating bottlenecks in isolation, we must account for systemic interdependencies.', 'Let us fix one tiny symptom and ignore everything else.', 'Isolated fixes always solve complex networks permanently.', 'Interdependencies have nothing to do with governance.'], correctIndex: 0, explanationVi: 'Tư duy hệ thống luôn xem xét các mối phụ thuộc lẫn nhau thay vì tách rời từng biểu hiện.' },
      { type: 'grammar', question: 'Chọn đáp án đúng: "The safeguards of aviation control systems are stricter than ___ consumer apps."', options: ['that of', 'those of', 'them of', 'which of'], correctIndex: 1, explanationVi: '"safeguards" là danh từ số nhiều -> dùng "those of" để so sánh tương xứng.' },
      { type: 'grammar', question: 'Chọn đáp án đúng: "Will autonomous tools replace human oversight entirely? Ethical boards strongly hope ___."', options: ['no', 'not', 'none', 'neither'], correctIndex: 1, explanationVi: 'Phủ định mệnh đề thay thế sau "hope" luôn dùng "hope not".' },
      { type: 'word_order', question: 'Sắp xếp câu đúng: [essential / Human / remains / high-risk / oversight / for / decisions / .]', options: ['Human oversight remains essential for high-risk decisions.', 'Essential remains human oversight for high-risk decisions.', 'High-risk decisions remains essential for human oversight.', 'Human remains oversight essential for high-risk decisions.'], correctIndex: 0, explanationVi: 'Cấu trúc chuẩn: S (Human oversight) + remains + essential + for high-risk decisions.' },
      { type: 'reading_comprehension', passage: 'In an interdependent digital ecosystem, altering one technical threshold rarely produces isolated effects. When organizations deploy autonomous tools without adequate auditability, minor biases can scale into systemic failures. Effective governance therefore requires calibrating oversight mechanisms continuously rather than relying on one-time rules.', question: 'Theo đoạn văn, điều gì có thể xảy ra nếu triển khai công cụ tự hành mà thiếu khả năng kiểm toán?', options: ['Hệ thống sẽ chạy nhanh hơn mà không có rủi ro', 'Những thiên lệch nhỏ có thể khuếch đại thành sự cố mang tính hệ thống', 'Quy định pháp lý sẽ tự động đơn giản hóa', 'Chi phí vận hành giảm về mức bằng không'], correctIndex: 1, explanationVi: 'Đoạn văn viết: "minor biases can scale into systemic failures".' },
      { type: 'reading_comprehension', passage: 'In an interdependent digital ecosystem, altering one technical threshold rarely produces isolated effects. When organizations deploy autonomous tools without adequate auditability, minor biases can scale into systemic failures. Effective governance therefore requires calibrating oversight mechanisms continuously rather than relying on one-time rules.', question: 'Quản trị hiệu quả đòi hỏi cách tiếp cận nào?', options: ['Ban hành một quy định duy nhất dùng mãi mãi', 'Liên tục hiệu chỉnh cơ chế giám sát thay vì chỉ dựa vào quy định một lần', 'Cấm hoàn toàn công cụ tự hành', 'Tách rời từng bộ phận để tự quản lý riêng'], correctIndex: 1, explanationVi: 'Câu cuối nêu rõ: "calibrating oversight mechanisms continuously rather than relying on one-time rules".' },
    ],
